// ประกอบ prompt + ข้อมูล JSON ส่ง OpenAI (ข้อมูลไม่มีชื่อ/เบอร์ลูกค้า)
const rep = $input.first().json;
const sys = "คุณคือที่ปรึกษาฝ่ายขายของศูนย์รถยนต์ไฟฟ้า WULING Chonburi เขียนบทวิเคราะห์สั้นให้เจ้าของ
ได้รับ JSON ตัวเลขรวมจากระบบ Sale Lead (ไม่มีชื่อ/เบอร์ลูกค้า) ตารางตัวเลขและสถานะไฟระบบสร้างให้แล้ว หน้าที่ของคุณคือบอกว่า "ตัวเลขนี้หมายความว่าอะไร และต้องทำอะไร" เท่านั้น ห้ามเล่าตัวเลขซ้ำยาวๆ

กติกา
1. ใช้เฉพาะตัวเลขใน JSON ห้ามเดา ข้อมูลไม่พอให้บอกว่าขาดอะไร
2. ห้ามตัดสินใจเรื่องการค้า (ราคา ส่วนลด เปลี่ยนเจ้าของลีด อนุมัติ) ให้เสนอเป็น "ข้อเสนอให้ผู้จัดการพิจารณา"
3. ห้ามใส่ชื่อ/เบอร์ลูกค้า อ้างลีดด้วย lead_code เท่านั้น
4. ห้ามสรุปว่าเซลล์คนไหนดีหรือแย่จากตัวเลขเดียว
5. จอง/สินเชื่อ/ส่งมอบ/ปิดการขาย นับเฉพาะ verified = true
6. ตัวเลขบันทึกผลติดต่อคือที่บันทึกในระบบ ไม่ใช่จำนวนสายจริง
7. งานค้างลีดเก่า (ก่อน 3 พ.ย. 2026) แยกจากงานค้างลีดใหม่ ให้ประเมินวินัยจากลีดใหม่เป็นหลัก
8. ไม่ใช้อีโมจิ ไม่ใช้ markdown ภาษาไทย ประโยคสั้น
9. ยาวไม่เกิน 1,200 ตัวอักษร

รูปแบบ (ตามนี้เท่านั้น)
สิ่งที่เห็น: 3 ข้อ ข้อละ 1 ประโยค
ต้องตัดสินใจสัปดาห์นี้: 3 ข้อ เรียงตามความสำคัญ แต่ละข้อบอกว่าใครควรทำอะไร
ข้อมูลที่ขาด/น่าสงสัย: ไม่เกิน 2 ข้อ (ถ้าไม่มีให้เขียน ไม่มี)";
const days = rep.period_days || 7;
const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const pad = (v, n) => String(v).padEnd(n);
const num = (v) => Number(v) || 0;
const light = (ok, warn) => ok ? '🟢' : (warn ? '🟡' : '🔴');
const S = rep.sales || [];
const sum = (k) => S.reduce((a, x) => a + num(x[k]), 0);
const newLeads = sum('leads_assigned'), prevLeads = sum('leads_assigned_prev');
const notCont = sum('not_contacted'), ovNew = sum('overdue_tasks_new'), ovOld = sum('overdue_tasks_legacy');
const hrs = S.map(x => x.avg_hours_to_first_contact).filter(x => x !== null && x !== undefined).map(Number);
const avgH = hrs.length ? hrs.reduce((a, b) => a + b, 0) / hrs.length : null;
const book = sum('bookings_reported'), bookV = sum('bookings_verified_total');
const unassigned = num(rep.unassigned_leads);
const table = S.map(x => '<b>' + esc(x.code) + '</b>  ใหม่ ' + num(x.leads_assigned) + ' · ติดต่อแล้ว ' + num(x.contacted) + ' · ค้าง ' + num(x.not_contacted) + ' · เลยกำหนด ' + num(x.overdue_tasks_new) + ' · เร็ว ' + (x.avg_hours_to_first_contact === null ? '-' : x.avg_hours_to_first_contact + ' ชม.')).join('
');
const trend = prevLeads ? (newLeads >= prevLeads ? '▲' : '▼') + ' ' + Math.abs(Math.round((newLeads - prevLeads) * 100 / prevLeads)) + '% จากช่วงก่อน' : 'ไม่มีช่วงก่อนเทียบ';
const digest = '<b>📊 รายงานฝ่ายขาย WULING Chonburi</b>
' + days + ' วันล่าสุด

' +
  light(newLeads > 0, false) + ' ลีดใหม่ <b>' + newLeads + '</b> (' + trend + ')
' +
  light(avgH !== null && avgH <= 4, avgH !== null && avgH <= 8) + ' ติดต่อครั้งแรกเฉลี่ย <b>' + (avgH === null ? '-' : avgH.toFixed(1) + ' ชม.') + '</b> (เป้า ≤ 4 ชม.)
' +
  light(notCont === 0, notCont <= 3) + ' ยังไม่ได้ติดต่อ <b>' + notCont + '</b> ลีด
' +
  light(ovNew === 0, ovNew <= 5) + ' งานเลยกำหนด (ลีดใหม่) <b>' + ovNew + '</b>
' +
  light(unassigned === 0, false) + ' ลีดไม่มีผู้ดูแล <b>' + unassigned + '</b>
' +
  '📌 จอง <b>' + book + '</b> (ยืนยันแล้วสะสม ' + bookV + ')

' +
  '<b>รายคน</b>
' + table + '

' +
  '<i>งานค้างลีดเก่าก่อน 3 พ.ย. แยกนับ: ' + ovOld + ' งาน (ไม่รวมในไฟด้านบน)</i>';
const user = 'ช่วงรายงาน: ' + days + ' วันล่าสุด (สร้างเมื่อ ' + rep.generated_at + ')

ข้อมูล JSON:
' + JSON.stringify(rep);
return [{ json: { digest, body: JSON.stringify({ model: 'gpt-4.1', temperature: 0.2, messages: [{ role: 'system', content: sys }, { role: 'user', content: user }] }) } }];

// แบ่งข้อความตามขีดจำกัด Telegram (4096) และ escape สำหรับโหมด HTML
const cfg = $('Config').first().json;
const res = $input.first().json;
const content = String(res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content || '').trim();
if (!content) throw new Error('AI ไม่ส่งข้อความรายงานกลับมา');
const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const digest = $('Build prompt').first().json.digest;
const text = '<b>🧠 วิเคราะห์และข้อเสนอ</b>\n' + esc(content);
const parts = []; let cur = '';
for (const l of text.split('\n')) { if ((cur + '\n' + l).length > 3800 && cur) { parts.push(cur); cur = l; } else { cur = cur ? cur + '\n' + l : l; } }
if (cur) parts.push(cur);
return [digest].concat(parts).map(p => ({ json: { chatId: String(cfg.adminChatId), text: p } }));

// สร้างรายงานรายคน: ตัวเลขสรุปคำนวณเองในโค้ด + prompt ให้ AI วิเคราะห์เชิงคุณภาพ (ไม่มีชื่อ/เบอร์ลูกค้า)
const rep = $input.first().json;
const cfg = $('Config').first().json;
const sys = "คุณคือโค้ชฝ่ายขายของศูนย์รถยนต์ไฟฟ้า WULING Chonburi เขียนรายงานผลงานรายบุคคลให้เจ้าของ\nได้รับ JSON ของเซลล์ 1 คน (quant = ตัวเลขปริมาณ, quality = ตัวเลขพฤติกรรมการทำงาน, team = ค่าเฉลี่ยทีมไว้เทียบ) ไม่มีชื่อ/เบอร์ลูกค้า\n\nกติกา\n1. ใช้เฉพาะตัวเลขใน JSON ห้ามเดา ข้อมูลไม่พอให้บอกว่าขาดอะไร\n2. ห้ามตัดสินใจเรื่องการค้า (ราคา ส่วนลด เปลี่ยนเจ้าของลีด) และห้ามตัดสินคนจากตัวเลขเดียว ให้เสนอเป็นข้อเสนอให้ผู้จัดการพิจารณา\n3. ตัวเลขบันทึกในระบบไม่ใช่จำนวนสายจริง บันทึกน้อยให้เขียนว่า \"ยังไม่ได้บันทึก\" ไม่ใช่ \"ไม่ทำงาน\"\n4. งานค้างลีดเก่าก่อน 3 พ.ย. 2026 ไม่นำมาประเมินวินัย\n5. ห้ามใส่ชื่อ/เบอร์ลูกค้า อ้างลีดด้วย lead_code เท่านั้น\n6. ไม่ใช้อีโมจิ ไม่ใช้ markdown ภาษาไทย ประโยคสั้น น้ำเสียงให้เกียรติ ใช้สำหรับพัฒนาคน\n7. ยาวไม่เกิน 1,400 ตัวอักษร\n\nรูปแบบ (ตามนี้เท่านั้น)\nเชิงปริมาณ: 2-3 ข้อ (ปริมาณงานเทียบทีมและเทียบช่วงก่อนหน้า)\nเชิงคุณภาพ: 3 ข้อ จากข้อมูลพฤติกรรม เช่น ความเร็วตอบสนอง สัดส่วนติดต่อสำเร็จต่อไม่รับสาย ความต่อเนื่องในการทำงานรายวัน การตั้งนัดติดตามต่อ การไล่ระดับความร้อนของลีด การเลื่อนสถานะ\nจุดเด่น: 1-2 ข้อ\nจุดที่ควรพัฒนา: 1-2 ข้อ\nข้อเสนอการโค้ช: 3 ข้อ สิ่งที่ผู้จัดการควรคุยหรือช่วย (ไม่ใช่คำสั่ง)\nลีดที่ควรติดตามก่อน: lead_code ไม่เกิน 5 รายการจาก risk_leads (ถ้าไม่มีให้เขียน ไม่มี)\nข้อมูลที่ขาด: ไม่เกิน 2 ข้อ (ถ้าไม่มีให้เขียน ไม่มี)";
const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const num = (v) => Number(v) || 0;
const pct = (a, b) => b ? Math.round(a * 100 / b) + '%' : '-';
const S = rep.sales || [], Q = rep.sales_quality || [], risk = rep.risk_leads || [];
const avg = (k) => S.length ? S.reduce((a, x) => a + num(x[k]), 0) / S.length : 0;
const team = { leads_assigned: avg('leads_assigned'), contacted: avg('contacted'), not_contacted: avg('not_contacted'), contact_logs: avg('contact_logs'), overdue_tasks_new: avg('overdue_tasks_new') };
const hrs = S.map(x => x.avg_hours_to_first_contact).filter(x => x !== null && x !== undefined).map(Number);
team.avg_hours_to_first_contact = hrs.length ? +(hrs.reduce((a, b) => a + b, 0) / hrs.length).toFixed(1) : null;
const days = rep.period_days || 7;
const out = [];
for (const x of S) {
  const q = Q.find(y => y.code === x.code) || {};
  const o = q.contact_outcomes || {};
  const ok = num(o.CONNECTED) + num(o.REPLIED), noans = num(o.NO_ANSWER), msg = num(o.MESSAGE_SENT), wrong = num(o.WRONG_NUMBER);
  const att = ok + noans + msg + wrong;
  const fc = num(q.first_contact_within_1h) + num(q.first_contact_1_to_4h) + num(q.first_contact_4_to_24h) + num(q.first_contact_over_24h);
  const mine = risk.filter(r => r.sales === x.code).slice(0, 5);
  const lines = [
    '<b>👤 ' + esc(x.code) + ' ' + esc(x.name || '') + '</b> (' + days + ' วัน)', '',
    '<b>เชิงปริมาณ</b>',
    '• ลีดใหม่ ' + num(x.leads_assigned) + ' (ช่วงก่อน ' + num(x.leads_assigned_prev) + ', เฉลี่ยทีม ' + team.leads_assigned.toFixed(0) + ')',
    '• ติดต่อแล้ว ' + num(x.contacted) + ' · ยังไม่ติดต่อ ' + num(x.not_contacted) + ' · HOT ' + num(x.hot_leads_assigned),
    '• บันทึกผลติดต่อ ' + num(x.contact_logs) + ' ครั้ง (ช่วงก่อน ' + num(x.contact_logs_prev) + ')',
    '• งานเลยกำหนด ลีดใหม่ ' + num(x.overdue_tasks_new) + ' · ลีดเก่า ' + num(x.overdue_tasks_legacy),
    '• จอง ' + num(x.bookings_reported) + ' · เสียโอกาสในช่วง ' + num(x.lost_in_period) + ' · ลีดที่กำลังดูแล ' + num(x.active_leads),
    '• ติดต่อครั้งแรกเฉลี่ย ' + (x.avg_hours_to_first_contact === null || x.avg_hours_to_first_contact === undefined ? '-' : x.avg_hours_to_first_contact + ' ชม.') + ' (ทีม ' + (team.avg_hours_to_first_contact === null ? '-' : team.avg_hours_to_first_contact + ' ชม.') + ')',
    '', '<b>เชิงคุณภาพ (จากพฤติกรรมในระบบ)</b>',
    '• ติดต่อครั้งแรกใน 1 ชม. ' + num(q.first_contact_within_1h) + ' · 1-4 ชม. ' + num(q.first_contact_1_to_4h) + ' · 4-24 ชม. ' + num(q.first_contact_4_to_24h) + ' · เกิน 24 ชม. ' + num(q.first_contact_over_24h),
    '• ผลการติดต่อ: สำเร็จ ' + ok + ' · ไม่รับสาย ' + noans + ' · ส่งข้อความ ' + msg + ' · เบอร์ผิด ' + wrong + ' (สำเร็จ ' + pct(ok, att) + ')',
    '• ทำงานต่อเนื่อง ' + num(q.active_days) + '/' + days + ' วัน · ตอบแจ้งเตือนผ่าน Telegram ' + num(q.telegram_replies) + ' ครั้ง',
    '• ลีดที่ตั้งนัดติดตามต่อ ' + num(q.active_with_next_followup) + '/' + num(q.active_total) + ' (' + pct(num(q.active_with_next_followup), num(q.active_total)) + ')',
    '• ลีดใหม่ที่เลื่อนไปถึงนัด/เสนอราคาขึ้นไป ' + num(q.assigned_now_advanced) + '/' + num(x.leads_assigned) + ' · เปลี่ยนสถานะ ' + num(q.stage_changes) + ' ครั้ง',
    '• ลีดที่ดูแล: HOT ' + num(q.active_hot) + ' · WARM ' + num(q.active_warm) + ' · COLD ' + num(q.active_cold) + ' · ยังไม่ประเมิน ' + num(q.active_temp_unset)
  ];
  const models = (q.models_requested || []).map(m => esc(m.model) + ' ' + m.n).join(', ');
  if (models) lines.push('• รุ่นที่ลูกค้าสนใจ: ' + models);
  const user = 'ช่วงรายงาน ' + days + ' วัน สร้างเมื่อ ' + rep.generated_at + '\n\nข้อมูลเซลล์ (JSON):\n' + JSON.stringify({ quant: x, quality: q, team, risk_leads: mine, note: rep.note });
  out.push({ json: { code: x.code, chatId: String(cfg.adminChatId), digest: lines.join('\n'), body: JSON.stringify({ model: 'gpt-4.1', temperature: 0.2, messages: [{ role: 'system', content: sys }, { role: 'user', content: user }] }) } });
}
return out;

// รวมตัวเลขรายคน + บทวิเคราะห์ AI เป็นข้อความเดียวต่อคน (แบ่งถ้าเกิน 3800 ตัวอักษร)
const esc = (v) => String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const items = $('สร้างรายงานรายคน').all();
const res = $input.all();
const outs = [];
res.forEach((r, i) => {
  const pi = r.pairedItem && r.pairedItem.item !== undefined ? r.pairedItem.item : i;
  const src = items[pi] ? items[pi].json : {};
  const content = String(r.json.choices && r.json.choices[0] && r.json.choices[0].message && r.json.choices[0].message.content || '').trim();
  const text = src.digest + '\n\n<b>🧠 วิเคราะห์และข้อเสนอโค้ช</b>\n' + esc(content || 'AI ไม่ส่งบทวิเคราะห์กลับมา (ดูตัวเลขด้านบนได้ตามปกติ)');
  const parts = []; let cur = '';
  for (const l of text.split('\n')) { if ((cur + '\n' + l).length > 3800 && cur) { parts.push(cur); cur = l; } else { cur = cur ? cur + '\n' + l : l; } }
  if (cur) parts.push(cur);
  parts.forEach(p => outs.push({ json: { chatId: src.chatId, text: p } }));
});
return outs;
